export interface BaseRecord {
  id: string;
  createdAt: string;
  updatedAt: string;
}

export const RESUME_STATUSES = [
  "ready",
  "extraction-failed",
  "needs-review",
  "deleted",
] as const;
export type ResumeStatus = (typeof RESUME_STATUSES)[number];

export const INTERVIEW_STATUSES = [
  "scheduled",
  "completed",
  "cancelled",
  "rescheduled",
] as const;
export type InterviewStatus = (typeof INTERVIEW_STATUSES)[number];

export const STAGE_KINDS = [
  "normal",
  "offer",
  "rejected",
  "withdrawn",
] as const;
export type StageKind = (typeof STAGE_KINDS)[number];

export interface Resume extends BaseRecord {
  name: string;
  type: "pdf" | "docx";
  fileName: string;
  fileSize: number;
  fileHash: string;
  uploadedAt: string;
  tags: string[];
  note: string;
  status: ResumeStatus;
  textSource?: "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type ResumeTextKind = "extracted" | "confirmed" | "manual";

export interface ResumeText extends BaseRecord {
  resumeId: string;
  kind: ResumeTextKind;
  text: string;
  confirmedAt?: string;
}

export interface JobDescription extends BaseRecord {
  applicationId: string;
  fileName?: string;
  fileType?: "pdf" | "docx";
  fileSize?: number;
  fileHash?: string;
  textSource: "pasted" | "extracted" | "manual";
  textConfirmedAt?: string;
  originalFileId?: string;
}

export type JobDescriptionTextKind =
  | "pasted"
  | "extracted"
  | "confirmed"
  | "manual";

export interface JobDescriptionText extends BaseRecord {
  jobDescriptionId: string;
  kind: JobDescriptionTextKind;
  text: string;
  confirmedAt?: string;
}

export interface Application extends BaseRecord {
  company: string;
  position: string;
  jobType: "graduate" | "internship" | "tech" | "general" | "other";
  location: string;
  workMode: "onsite" | "remote" | "hybrid" | "unknown";
  salaryText: string;
  source: string;
  jobUrl: string;
  jdText: string;
  jdFileId?: string;
  currentResumeId?: string;
  stageId: string;
  priority: number;
  deadline?: string;
  contact: string;
  note: string;
  archivedAt?: string;
}

export interface ResumeUsageHistory extends BaseRecord {
  applicationId: string;
  resumeId: string;
  resumeNameSnapshot: string;
  textSnapshot: string;
  usedAt: string;
}

export interface Stage extends BaseRecord {
  name: string;
  color: string;
  order: number;
  kind: StageKind;
}

export type TimelineEventType =
  | "stage-changed"
  | "resume-changed"
  | "note-added"
  | "archived"
  | "interview-rescheduled";

export interface ApplicationTimelineEvent extends BaseRecord {
  applicationId: string;
  type: TimelineEventType;
  fromValue?: string;
  toValue?: string;
  note: string;
}

export interface Reminder {
  offsetMinutes: number;
  channel: "in-app" | "browser";
}

export interface Interview extends BaseRecord {
  applicationId: string;
  round: number;
  type: "phone" | "video" | "onsite" | "assessment" | "other";
  title: string;
  startsAt: string;
  endsAt?: string;
  timezone: string;
  locationOrLink: string;
  interviewer: string;
  status: InterviewStatus;
  reminders: Reminder[];
  calendarExportedAt?: string;
  note: string;
}

export interface ReviewQuestion {
  question: string;
  answer?: string;
  note?: string;
}

export interface InterviewReview extends BaseRecord {
  interviewId: string;
  overallRating?: number;
  questions: ReviewQuestion[];
  goodAnswers: string;
  weakAnswers: string;
  observedSignals: string;
  salaryDiscussion: string;
  nextStep: string;
  privateNote: string;
}

export interface AnalysisCoverage {
  overall: number;
  required: number;
  preferred: number;
}

export interface AnalysisEvidence {
  keyword: string;
  excerpt: string;
}

export interface AnalysisResult extends BaseRecord {
  applicationId: string;
  resumeId: string;
  mode: "local" | "ai";
  coverage: AnalysisCoverage;
  matchedKeywords: string[];
  weakMatches: string[];
  missingKeywords: string[];
  evidence: AnalysisEvidence[];
  uncertainItems: string[];
  recommendations: string[];
}

export interface AiMessage {
  id: string;
  role: "system" | "user" | "assistant";
  content: string;
  createdAt: string;
}

export interface AiConversation extends BaseRecord {
  applicationId: string;
  messages: AiMessage[];
}

export interface StoredFile extends BaseRecord {
  ownerType: "resume" | "job-description";
  ownerId: string;
  fileName: string;
  fileType: "pdf" | "docx";
  blob: Blob;
}

export interface SensitiveSettingsRecord extends BaseRecord {
  id: "ai";
  apiUrl: string;
  model: string;
  apiKey: string;
  organizationId: string;
  customHeaders: Record<string, string>;
}

export interface DomainRecordMap {
  resumes: Resume;
  resumeTexts: ResumeText;
  jobDescriptions: JobDescription;
  jobDescriptionTexts: JobDescriptionText;
  applications: Application;
  resumeUsageHistory: ResumeUsageHistory;
  stages: Stage;
  applicationTimelineEvents: ApplicationTimelineEvent;
  interviews: Interview;
  interviewReviews: InterviewReview;
  analysisResults: AnalysisResult;
  aiConversations: AiConversation;
  originalFiles: StoredFile;
}

export type DomainStoreName = keyof DomainRecordMap;
export const DATABASE_NAME = "local-career-workspace";
export const DATABASE_VERSION = 5;

export const STORE_NAMES = {
  resumes: "resumes",
  resumeTexts: "resumeTexts",
  jobDescriptions: "jobDescriptions",
  jobDescriptionTexts: "jobDescriptionTexts",
  applications: "applications",
  resumeUsageHistory: "resumeUsageHistory",
  stages: "stages",
  applicationTimelineEvents: "applicationTimelineEvents",
  interviews: "interviews",
  interviewReviews: "interviewReviews",
  analysisResults: "analysisResults",
  aiConversations: "aiConversations",
  originalFiles: "originalFiles",
  sensitiveSettings: "sensitiveSettings",
} as const;

export type StoreName = (typeof STORE_NAMES)[keyof typeof STORE_NAMES];

interface IndexDefinition {
  name: string;
  keyPath: string | string[];
  unique?: boolean;
}

const INDEXES: Record<StoreName, readonly IndexDefinition[]> = {
  resumes: [
    { name: "status", keyPath: "status" },
    { name: "fileHash", keyPath: "fileHash" },
    { name: "updatedAt", keyPath: "updatedAt" },
  ],
  resumeTexts: [
    { name: "resumeId", keyPath: "resumeId" },
    { name: "resumeId_kind", keyPath: ["resumeId", "kind"], unique: true },
  ],
  jobDescriptions: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "fileHash", keyPath: "fileHash" },
  ],
  jobDescriptionTexts: [
    { name: "jobDescriptionId", keyPath: "jobDescriptionId" },
    {
      name: "jobDescriptionId_kind",
      keyPath: ["jobDescriptionId", "kind"],
      unique: true,
    },
  ],
  applications: [
    { name: "stageId", keyPath: "stageId" },
    { name: "currentResumeId", keyPath: "currentResumeId" },
    { name: "updatedAt", keyPath: "updatedAt" },
  ],
  resumeUsageHistory: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "resumeId", keyPath: "resumeId" },
  ],
  stages: [
    { name: "kind", keyPath: "kind" },
    { name: "order", keyPath: "order" },
  ],
  applicationTimelineEvents: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "createdAt", keyPath: "createdAt" },
  ],
  interviews: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "startsAt", keyPath: "startsAt" },
    { name: "status", keyPath: "status" },
  ],
  interviewReviews: [
    { name: "interviewId", keyPath: "interviewId", unique: true },
  ],
  analysisResults: [
    { name: "applicationId", keyPath: "applicationId" },
    { name: "resumeId", keyPath: "resumeId" },
    { name: "createdAt", keyPath: "createdAt" },
  ],
  aiConversations: [{ name: "applicationId", keyPath: "applicationId" }],
  originalFiles: [
    { name: "ownerId", keyPath: "ownerId" },
    {
      name: "ownerType_ownerId",
      keyPath: ["ownerType", "ownerId"],
      unique: true,
    },
  ],
  sensitiveSettings: [],
};

export function ensureSchema(
  database: IDBDatabase,
  transaction: IDBTransaction,
): void {
  for (const storeName of Object.values(STORE_NAMES)) {
    const store = database.objectStoreNames.contains(storeName)
      ? transaction.objectStore(storeName)
      : database.createObjectStore(storeName, { keyPath: "id" });

    for (const index of INDEXES[storeName]) {
      if (!store.indexNames.contains(index.name)) {
        store.createIndex(index.name, index.keyPath, {
          unique: index.unique ?? false,
        });
      }
    }
  }
}

import { unzipSync } from "fflate";

import { requestToPromise, runTransaction } from "../../db/database";
import { STORE_NAMES } from "../../db/schema";
import { assertAbsoluteIsoTimestamp, nextUpdatedTimestamp } from "../../db/timestamps";
import type {
  Application,
  JobDescription,
  JobDescriptionText,
  StoredFile,
} from "../../db/types";
import { parseDocx } from "../../parsers/docx";
import { parsePdf } from "../../parsers/pdf";

export const MAX_JOB_DESCRIPTION_FILE_SIZE = 25 * 1024 * 1024;

const MIME_TYPES = {
  pdf: "application/pdf",
  docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
} as const;
type JobDescriptionFileType = keyof typeof MIME_TYPES;

export type JobDescriptionIngestionErrorCode =
  | "unsupported-format"
  | "type-mismatch"
  | "file-too-large"
  | "invalid-file"
  | "duplicate-file"
  | "application-not-found"
  | "job-description-not-found"
  | "original-file-missing";

export type JobDescriptionRecoveryActionCode =
  | "choose-pdf-or-docx"
  | "choose-matching-file"
  | "choose-smaller-file"
  | "choose-valid-file"
  | "use-existing-job-description"
  | "paste-or-correct-text"
  | "select-existing-job-description";

export interface JobDescriptionRecoveryAction {
  code: JobDescriptionRecoveryActionCode;
  message: string;
}

export interface JobDescriptionFileMetadata {
  fileName: string;
  mimeType: string;
  fileSize: number;
  fileType?: JobDescriptionFileType;
  fileHash?: string;
  status?: JobDescription["textSource"];
}

export class JobDescriptionIngestionError extends Error {
  readonly code: JobDescriptionIngestionErrorCode;
  readonly action: JobDescriptionRecoveryAction;
  readonly metadata: JobDescriptionFileMetadata;
  readonly existingJobDescriptionId?: string;

  constructor(options: {
    code: JobDescriptionIngestionErrorCode;
    message: string;
    action: JobDescriptionRecoveryAction;
    metadata: JobDescriptionFileMetadata;
    existingJobDescriptionId?: string;
  }) {
    super(options.message);
    this.name = "JobDescriptionIngestionError";
    this.code = options.code;
    this.action = options.action;
    this.metadata = options.metadata;
    this.existingJobDescriptionId = options.existingJobDescriptionId;
  }

  toJSON(): Record<string, unknown> {
    return {
      name: this.name,
      code: this.code,
      message: this.message,
      action: this.action,
      metadata: this.metadata,
      ...(this.existingJobDescriptionId
        ? { existingJobDescriptionId: this.existingJobDescriptionId }
        : {}),
    };
  }
}

export interface JobDescriptionLogEntry {
  event:
    | "job-description-pasted"
    | "job-description-ingested"
    | "job-description-extraction-failed"
    | "job-description-extraction-retried";
  metadata: JobDescriptionFileMetadata;
}

export interface JobDescriptionIngestionDependencies {
  now?: () => string;
  createId?: () => string;
  parseText?: (fileType: JobDescriptionFileType, data: ArrayBuffer) => Promise<string>;
  logger?: (entry: JobDescriptionLogEntry) => void;
}

export interface PasteResult {
  jobDescription: JobDescription;
  text: JobDescriptionText;
}

export interface JobDescriptionIngestionResult {
  outcome: "needs-review" | "extraction-failed";
  jobDescription: JobDescription;
  extractedText?: JobDescriptionText;
  recovery?: {
    code: "extraction-failed";
    action: JobDescriptionRecoveryAction;
    metadata: JobDescriptionFileMetadata;
  };
}

export interface JobDescriptionConfirmResult {
  jobDescription: JobDescription;
  text: JobDescriptionText;
  application: Application;
}

const ACTIONS = {
  chooseSupported: { code: "choose-pdf-or-docx", message: "Choose a PDF or DOCX file." },
  chooseMatching: { code: "choose-matching-file", message: "Choose a file whose extension and MIME type match." },
  chooseSmaller: { code: "choose-smaller-file", message: "Choose a file no larger than 25 MB." },
  chooseValid: { code: "choose-valid-file", message: "Choose a valid, unmodified PDF or DOCX file." },
  useExisting: { code: "use-existing-job-description", message: "Use the job description that was already imported." },
  pasteText: { code: "paste-or-correct-text", message: "Paste or correct the job description text manually." },
  selectExisting: { code: "select-existing-job-description", message: "Select an existing job description and try again." },
} as const satisfies Record<string, JobDescriptionRecoveryAction>;

function extensionOf(fileName: string): string | undefined {
  const dot = fileName.lastIndexOf(".");
  return dot < 0 ? undefined : fileName.slice(dot + 1).toLowerCase();
}

function fileMetadata(file: File, fileType?: JobDescriptionFileType): JobDescriptionFileMetadata {
  return { fileName: file.name, mimeType: file.type, fileSize: file.size, ...(fileType ? { fileType } : {}) };
}

function errorFor(
  code: JobDescriptionIngestionErrorCode,
  message: string,
  action: JobDescriptionRecoveryAction,
  metadata: JobDescriptionFileMetadata,
  existingJobDescriptionId?: string,
): JobDescriptionIngestionError {
  return new JobDescriptionIngestionError({ code, message, action, metadata, ...(existingJobDescriptionId ? { existingJobDescriptionId } : {}) });
}

function validateFileMetadata(file: File): JobDescriptionFileType {
  const extension = extensionOf(file.name);
  if (extension !== "pdf" && extension !== "docx") {
    throw errorFor("unsupported-format", "Only PDF and DOCX job description files are supported.", ACTIONS.chooseSupported, fileMetadata(file));
  }
  if (file.size > MAX_JOB_DESCRIPTION_FILE_SIZE) {
    throw errorFor("file-too-large", "The job description file exceeds the 25 MB limit.", ACTIONS.chooseSmaller, fileMetadata(file, extension));
  }
  if (file.type.toLowerCase() !== MIME_TYPES[extension]) {
    throw errorFor("type-mismatch", "The job description extension and MIME type do not match.", ACTIONS.chooseMatching, fileMetadata(file, extension));
  }
  return extension;
}

function hasPrefix(data: Uint8Array, prefix: readonly number[]): boolean {
  return prefix.every((byte, index) => data[index] === byte);
}

function validateFileContents(file: File, fileType: JobDescriptionFileType, data: Uint8Array): void {
  let valid = false;
  if (fileType === "pdf") {
    const source = new TextDecoder("latin1").decode(data);
    valid = hasPrefix(data, [0x25, 0x50, 0x44, 0x46, 0x2d]) && source.includes("%%EOF");
  } else if (hasPrefix(data, [0x50, 0x4b, 0x03, 0x04])) {
    try {
      const required = new Set(["[Content_Types].xml", "word/document.xml"]);
      const entries = unzipSync(data, { filter: (entry) => required.has(entry.name) });
      valid = [...required].every((name) => entries[name] !== undefined);
    } catch {
      valid = false;
    }
  }
  if (!valid) {
    throw errorFor("invalid-file", `The selected ${fileType.toUpperCase()} file is invalid.`, ACTIONS.chooseValid, fileMetadata(file, fileType));
  }
}

async function sha256(data: ArrayBuffer): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", data);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function defaultParseText(fileType: JobDescriptionFileType, data: ArrayBuffer): Promise<string> {
  return fileType === "pdf" ? parsePdf(data) : parseDocx(data);
}

async function blobArrayBuffer(blob: Blob): Promise<ArrayBuffer> {
  if (typeof blob.arrayBuffer === "function") return blob.arrayBuffer();
  return new Response(blob).arrayBuffer();
}

async function normalizeStoredFile(file: StoredFile): Promise<StoredFile> {
  const bytes = await blobArrayBuffer(file.blob);
  return { ...file, blob: new Blob([bytes], { type: file.blob.type }) };
}

function metadataFor(jobDescription: JobDescription, mimeType = ""): JobDescriptionFileMetadata {
  return {
    fileName: jobDescription.fileName ?? "",
    mimeType,
    fileSize: jobDescription.fileSize ?? 0,
    ...(jobDescription.fileType ? { fileType: jobDescription.fileType } : {}),
    ...(jobDescription.fileHash ? { fileHash: jobDescription.fileHash } : {}),
    status: jobDescription.textSource,
  };
}

export class JobDescriptionService {
  readonly #database: IDBDatabase;
  readonly #now: () => string;
