    assertAbsoluteIsoTimestamp(timestamp, "JobDescription.createdAt");
    let extracted: string | undefined;
    try {
      const parsed = await this.#parseText(fileType, data.slice(0));
      if (!parsed.trim()) throw new Error("No text layer");
      extracted = parsed;
