 82	function excerptAt(source: string, location: LocatedText): string {
 83	  const boundary = /[\n。！？!?；;]/u;
 84	  let start = location.start;
 85	  let end = location.end;
 86	  while (start > 0 && !boundary.test(source[start - 1] ?? "")) start -= 1;
 87	  while (end < source.length && !boundary.test(source[end] ?? "")) end += 1;
 88	  const full = source.slice(start, end).trim();
 89	  if (full.length <= 180) return full;
 90	  const localStart = Math.max(0, location.start - start - 70);
